import productApi from "@/apiRequest/product";
import Image from "next/image";

export default async function ProductDetailPage({ params }: { params: { id: string } }) {
  let product = null;
  try {
    const { payload } = await productApi.getDetail(Number(params.id));
    product = payload.data;
  } catch (error) {
    console.log(error);
  }
  return (
    <div className="p-2">
      {!product && <div>Không tìm thấy sản phẩm...</div>}
      {product && (
        <div className="space-y-2">
          <div>ID: {product.id}</div>
          <h1>{product.name}</h1>
          <h2>{product.description}</h2>
          <Image
            src={product.image}
            alt={product.name}
            width={200}
            height={200}
            className="w-32 h-32 object-cover"
          />
          <div>Giá: {product.price}</div>
          <div>Ngày tạo: {new Date(product.createdAt).toLocaleDateString("vi-VN")}</div>
          <div>Ngày cập nhật: {new Date(product.updatedAt).toLocaleDateString("vi-VN")}</div>
        </div>
      )}
    </div>
  );
}
